import torch, torch.nn.functional as F

@torch.no_grad()
def ema_update(key_enc, query_enc, m=0.99):
    for pk, pq in zip(key_enc.parameters(), query_enc.parameters()):
        pk.mul_(m).add_(pq, alpha=1 - m)

def info_nce(q, k_pos, queue, tau=0.07):
    # q, k_pos: (B, D) 정규화된 특징 / queue: (K, D) 과거 키(음성)
    pos = (q * k_pos).sum(1, keepdim=True)        # (B, 1)
    neg = q @ queue.T                              # (B, K)
    logits = torch.cat([pos, neg], 1) / tau
    target = torch.zeros(len(q), dtype=torch.long) # 정답은 0번 칸
    return F.cross_entropy(logits, target)
